const overview='https://www.indonesia.travel/id/id/destination/maluku-papua/north-maluku';
const traditions=[{title:'SOYA-SOYA',copy:'Gerakan yang membawa ingatan perjuangan. Soya-Soya berkaitan dengan sejarah Sultan Baabullah dan hadir dalam kehidupan budaya masyarakat Ternate. Kekompakan para penarinya menjadi bagian penting dari pengalaman pertunjukan.',source:'https://budaya.data.kemdikbud.go.id/wbtb/objek/AA000223',photo:'soya',caption:'TERNATE / SENI PERTUNJUKAN'},{title:'SASADU',copy:'Di Halmahera Barat, masyarakat Sahu bertemu di Sasadu. Ruang adat ini menjadi tempat bermusyawarah dan merayakan kebersamaan, termasuk ungkapan syukur atas panen melalui Orom Sasadu.',source:'https://www.indonesia.travel/id/id/travel-ideas/heritage/sasadu-traditional-house',photo:'sasadu',caption:'HALMAHERA BARAT / RUANG ADAT'},{title:'ARABABU',copy:'Bunyi juga menyimpan identitas. Arababu merupakan alat musik gesek yang dikenal di Maluku Utara. Mengenal alat musik tradisional membuka jalan untuk menghargai para pemain dan pengetahuan yang mereka teruskan.',source:overview,photo:null,caption:'MALUKU UTARA / KISAH MUSIK'}];
const islands=[{title:'TERNATE',copy:'Kedaton Ternate menjadi salah satu pintu untuk mengenal warisan kesultanan dan kehidupan adatnya.',source:overview},{title:'HALMAHERA',copy:'Kenali masyarakat Sahu melalui Sasadu: ruang pertemuan yang menghubungkan adat dengan kehidupan bersama.',source:traditions[1].source},{title:'MOROTAI',copy:'Dodola memperlihatkan sisi bahari Maluku Utara. Laut dan pesisir menjadi awal untuk memahami kehidupan kepulauan.',source:overview}];
const collection=[{title:'Soya-Soya',category:'Seni',place:'TERNATE',photo:'soya',summary:'Gerak, keberanian, dan ingatan bersama.',copy:traditions[0].copy,source:traditions[0].source},{title:'Sasadu',category:'Arsitektur',place:'HALMAHERA BARAT',photo:'sasadu',summary:'Ruang terbuka untuk merawat kebersamaan.',copy:traditions[1].copy,source:traditions[1].source},{title:'Kedaton Ternate',category:'Arsitektur',place:'TERNATE',photo:null,summary:'Mengenal ruang budaya kesultanan.',copy:'Kedaton Ternate menghubungkan warisan kesultanan dengan aktivitas adat. Buka rujukan untuk mengenal sejarahnya.',source:overview},{title:'Arababu',category:'Seni',place:'MALUKU UTARA',photo:null,summary:'Cerita yang hadir lewat alat musik gesek.',copy:traditions[2].copy,source:overview},{title:'Gohu Ikan',category:'Kuliner',place:'MALUKU UTARA',photo:null,summary:'Pertemuan hasil laut dan rasa segar.',copy:'Gohu ikan memadukan tuna atau cakalang dengan lemon cui dan bumbu. Kuliner ini memperlihatkan hubungan rasa dengan hasil laut setempat.',source:overview},{title:'Air Guraka',category:'Kuliner',place:'MALUKU UTARA',photo:null,summary:'Kehangatan jahe dalam satu cangkir.',copy:'Air guraka memadukan jahe merah, gula aren, dan kenari. Sebuah pengantar untuk mengenal khazanah minuman setempat.',source:overview}];
const $=s=>document.querySelector(s),$$=s=>[...document.querySelectorAll(s)];
function selectTradition(i){const t=traditions[i];$('#tradition-title').textContent=t.title;$('#tradition-copy').textContent=t.copy;$('#tradition-source').href=t.source;$('.number').textContent=`0${i+1} — 03`;const photo=$('.feature-photo');photo.querySelector('img').hidden=!t.photo;if(t.photo){photo.querySelector('img').src=`assets/${t.photo}.jpg`;photo.querySelector('img').alt=`Foto rujukan ${t.title}, Indonesia Travel`;}photo.querySelector('span').textContent=t.caption;photo.style.background=t.photo?'':'#29443a';let label=photo.querySelector('.photo-symbol');if(!label){label=document.createElement('b');label.className='photo-symbol';photo.append(label)}label.textContent=t.photo?'':'ARABABU / MUSIK';$$('[data-tradition]').forEach(b=>b.setAttribute('aria-pressed',Number(b.dataset.tradition)===i));}
$$('[data-tradition]').forEach(b=>b.addEventListener('click',()=>selectTradition(Number(b.dataset.tradition))));selectTradition(0);
function selectIsland(i){const t=islands[i];$('#island-title').textContent=t.title;$('#island-copy').textContent=t.copy;$('#island-source').href=t.source;$$('[data-island]').forEach(b=>b.setAttribute('aria-pressed',Number(b.dataset.island)===i));}$$('[data-island]').forEach(b=>b.onclick=()=>selectIsland(Number(b.dataset.island)));selectIsland(0);
const dialog=$('#detail');$('.close').onclick=()=>dialog.close();dialog.addEventListener('click',e=>{if(e.target===dialog){const r=dialog.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)dialog.close();}});
function openDetail(item){$('#detail-content').replaceChildren();const wrap=$('#detail-content');if(item.photo){const img=document.createElement('img');img.src=`assets/${item.photo}.jpg`;img.alt=`Foto rujukan ${item.title}, Indonesia Travel`;wrap.append(img)}const small=document.createElement('small');small.textContent=`${item.place} / ${item.category}`;const title=document.createElement('h2');title.textContent=item.title;const p=document.createElement('p');p.textContent=item.copy;const a=document.createElement('a');a.href=item.source;a.target='_blank';a.rel='noopener';a.textContent='Baca sumber lengkap ↗';wrap.append(small,title,p,a);if(item.photo){const credit=document.createElement('p');credit.textContent='Foto: Indonesia Travel / Kementerian Pariwisata. Hak foto mengikuti penerbit sumber.';wrap.append(credit)}dialog.showModal();}
let filter='Semua';function render(){const query=$('#search').value.trim().toLocaleLowerCase('id');const found=collection.filter(c=>(filter==='Semua'||c.category===filter)&&`${c.title} ${c.place} ${c.category}`.toLocaleLowerCase('id').includes(query));$('#collection-grid').replaceChildren();found.forEach(item=>{const b=document.createElement('button');b.className='collection-card';if(item.photo){const img=document.createElement('img');img.src=`assets/${item.photo}.jpg`;img.alt=`Foto rujukan ${item.title}`;img.loading='lazy';b.append(img)}else{const art=document.createElement('div');art.className='type-art';art.setAttribute('aria-hidden','true');art.textContent=item.title;art.dataset.type=item.category;b.append(art)}const div=document.createElement('div');const sm=document.createElement('small');sm.textContent=`${item.place} / ${item.category}`;const h=document.createElement('h3');h.textContent=item.title;const p=document.createElement('p');p.textContent=item.summary;const open=document.createElement('span');open.className='open';open.textContent='BUKA CERITA ↗';div.append(sm,h,p,open);b.append(div);b.onclick=()=>openDetail(item);$('#collection-grid').append(b)});$('#result-count').textContent=found.length?`${found.length} cerita untuk dijelajahi`:'Belum ada koleksi yang cocok. Coba kata lain atau pilih Semua.';}
$$('[data-filter]').forEach(b=>b.onclick=()=>{filter=b.dataset.filter;$$('[data-filter]').forEach(x=>x.setAttribute('aria-pressed',x===b));render()});$('#search').addEventListener('input',render);render();
$$('[data-answer]').forEach(b=>b.onclick=()=>{const correct=b.dataset.answer==='Sahu';$('#feedback').textContent=correct?'Tepat! Sasadu merupakan ruang adat masyarakat Sahu di Halmahera Barat.':'Belum tepat. Jawabannya Sahu, masyarakat yang merawat tradisi Sasadu di Halmahera Barat.';$$('[data-answer]').forEach(x=>x.setAttribute('aria-pressed',x===b));});
$('#sources-open').onclick=()=>{$('#detail-content').innerHTML='<h2>SUMBER & KREDIT</h2><p>MOLOKU adalah ruang edukasi independen. Narasi dirangkum dari rujukan berikut; keragaman praktik adat perlu dipahami melalui masyarakat pemiliknya.</p><p><a href="'+overview+'" target="_blank" rel="noopener">Indonesia Travel — Maluku Utara</a></p><p><a href="'+traditions[1].source+'" target="_blank" rel="noopener">Indonesia Travel — Sasadu</a></p><p><a href="'+traditions[0].source+'" target="_blank" rel="noopener">Pangkalan Data WBTb — Soya-Soya</a></p><p>Foto lanskap, Sasadu, dan Soya-Soya: Indonesia Travel / Kementerian Pariwisata. Hak cipta mengikuti penerbit. Panel tipografi merupakan desain editorial, bukan foto objek budaya. Situs ini tidak berafiliasi dengan pemerintah.</p>';dialog.showModal()};
let frame=false,currentScene='maluku';function update(){frame=false;const pos=scrollY+innerHeight*.45;let active=$$('.chapter')[0];$$('.chapter').forEach(s=>{if(s.offsetTop<=pos)active=s});const scene=active.dataset.scene;if(scene!==currentScene){currentScene=scene;$('#scene').src=`assets/${scene}.jpg`;}const navId=active.id==='ingatan'?'koleksi':active.id;$$('.dock a').forEach(a=>{if(a.hash==='#'+navId)a.setAttribute('aria-current','location');else a.removeAttribute('aria-current')});const total=document.documentElement.scrollHeight-innerHeight;$('.progress').style.width=(total?scrollY/total*100:0)+'%'}addEventListener('scroll',()=>{if(!frame){frame=true;requestAnimationFrame(update)}},{passive:true});update();
